        }
    }

    configurations {
        compileOnly {
            extendsFrom annotationProcessor
        }
    }

    repositories {
        mavenCentral()
    }

    dependencies {
        implementation 'org.springframework.boot:spring-boot-starter-data-jpa'
        implementation 'org.springframework.boot:spring-boot-starter-validation'
        implementation 'org.springframework.boot:spring-boot-starter-web'
        developmentOnly 'org.springframework.boot:spring-boot-devtools'
        runtimeOnly 'com.mysql:mysql-connector-j'
        testImplementation 'org.springframework.boot:spring-boot-starter-test'
        testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
        implementation 'at.favre.lib:bcrypt:0.10.2'

        // QueryDSL
        implementation "com.querydsl:querydsl-jpa:5.0.0:jakarta"
        annotationProcessor "com.querydsl:querydsl-apt:5.0.0:jakarta"
        annotationProcessor "jakarta.annotation:jakarta.annotation-api"
        annotationProcessor "jakarta.persistence:jakarta.persistence-api"

        // H2 Database
        runtimeOnly 'com.h2database:h2'

        // Replace the following with the starter dependencies of specific modules you wish to use
        implementation 'io.awspring.cloud:spring-cloud-aws-s3:3.2.1'


        // lombok
        annotationProcessor 'org.projectlombok:lombok'
        compileOnly 'org.projectlombok:lombok'
    }

    tasks.named('test') {
        useJUnitPlatform()
    }

    //querydsl 추가 시작
    def querydslDir = 'src/querydsl/generated'

    // querydsl QClass 파일 생성 위치를 지정
    tasks.withType(JavaCompile) {
        options.getGeneratedSourceOutputDirectory().set(file(querydslDir))
    }

    jacoco {
        toolVersion = '0.8.12'
    }

    jacocoTestReport {
        dependsOn tasks.named('test')
        reports {
            xml.required = false
            csv.required = false
            html.outputLocation = layout.buildDirectory.dir('jacocoHtml')
        }

        // QueryDsl Q Class 제외
        def Qdomains = []
        for(qPattern in "**/QA" .. "**/QZ"){
            Qdomains.add(qPattern+"*")
        }

        // QueryDsl Q Class 제외
        afterEvaluate {
            getClassDirectories().setFrom(classDirectories.files.collect {
                fileTree(dir: it, exclude: ['**/*Application*',
                                            '**/*Exception*',
                                            '**/dto/**',
                                            "GlobalConstants"] + Qdomains)
            })
        }

        finalizedBy 'jacocoTestCoverageVerification' // 추가
    }

    // 커버리지 수준을 설정
    // rule 적용
    jacocoTestCoverageVerification {
        // QueryDsl Q Class 제외
        def Qdomains = []
        for (qPattern in "*.QA".."*.QZ") {  // qPattern = "*.QA","*.QB","*.QC", ... "*.QZ"
            Qdomains.add(qPattern + "*")
        } // 이부분을 지정

        violationRules {
            rule {
                enabled = true
                element = 'BUNDLE'
                limit {
                    counter = 'METHOD'
                    value = 'COVEREDRATIO'
                    minimum = 0.1
                }
                excludes = ['**/*Application*',
                            '**/*Exception*',
                            '**/dto/**',
                "GlobalConstants"] + Qdomains
            }
        }
    }
